  "MiniRow(children: any[], gap?: number, align?: \"start\" | \"center\" | \"end\" | \"stretch\", justify?: \"start\" | \"center\" | \"end\" | \"between\", wrap?: boolean) — Horizontal group; gap uses 4px steps.",
  "MiniColumn(children: any[], gap?: number, align?: \"start\" | \"center\" | \"end\" | \"stretch\") — Vertical group; preserves app scope.",
