  "MiniText(text: string, kind?: \"heading\" | \"body\" | \"caption\" | \"display\", align?: \"start\" | \"center\" | \"end\", tone?: \"default\" | \"muted\" | \"success\" | \"danger\") — Reactive text with heading, body, caption or prominent display hierarchy. Semantic tone only.",
  "Svg(children: any[], viewBox: string, width?: number, height?: number, title?: string) — Responsive SVG drawing; shapes and text accept reactive expressions. Supply a title in the user language for meaningful drawings, otherwise decorative. Semantic paints foreground, muted, primary, accent, destructive, chart-1 through chart-5; hex colors allowed. No HTML or resource URLs.",
  "Circle(cx: number, cy: number, r: number, fill?: string, stroke?: string, strokeWidth?: number, opacity?: number) — Filled circle.",
